/// A single condition reading written on-chain by the oracle layer via
/// `recordSensorEvent()`. In the current build these are generated by
/// [MockChainService]; once the oracle bridge exists this model is read
/// straight from ledger query results without any UI changes.
class SensorEvent {
  final String id;
  final DateTime timestamp;
  final double temperatureC;
  final double humidityPct;
  final String location;
  final String txHash;

  const SensorEvent({
    required this.id,
    required this.timestamp,
    required this.temperatureC,
    required this.humidityPct,
    required this.location,
    required this.txHash,
  });
}
